pub fn hundredths(text: &str) -> i64 {
    let (whole, fraction) = text.split_once('.').unwrap_or((text, ""));
    let padded = format!("{fraction:0<2}");
    whole.parse::<i64>().unwrap() * 100 + padded.parse::<i64>().unwrap()
